"use client";

import * as React from "react";

// Base UI has no AspectRatio primitive, so this is a plain div with the CSS
// aspect-ratio property. The relative position and full width keep absolutely
// positioned children (such as next/image with fill) inside the box.

export interface AspectRatioProps
  extends React.ComponentPropsWithoutRef<"div"> {
  ratio?: number;
}

/** Ink mail AspectRatio: holds a screenshot or preview at a fixed shape. */
const AspectRatio = React.forwardRef<HTMLDivElement, AspectRatioProps>(
  ({ ratio = 1, style, ...props }, ref) => (
    <div
      ref={ref}
      data-slot="aspect-ratio"
      style={{
        position: "relative",
        width: "100%",
        aspectRatio: String(ratio),
        ...style,
      }}
      {...props}
    />
  ),
);
AspectRatio.displayName = "AspectRatio";

export { AspectRatio };
